using System.Data;
using Essco.Application.Products;
using Essco.Domain.Products;
using Microsoft.Data.SqlClient;
namespace Essco.Infrastructure.Data;

public sealed class SqlServerProductRepository(string connectionString, int timeout) : IProductRepository
{
    public async ValueTask<IReadOnlyCollection<Product>> ListAsync(ProductFilter f, CancellationToken t) { await using var c = await Open(t); await using var cmd = Command("", c); var w = new List<string>(); if (!string.IsNullOrWhiteSpace(f.ProductType) && f.ProductType != "*") { w.Add("[TipoProducto]=@Type"); P(cmd, "@Type", 100, f.ProductType); } if (!string.IsNullOrWhiteSpace(f.Search)) { var col = f.SearchDescription ? "[Descripcion]" : "[ItemCode]"; w.Add($"{col} LIKE @Search"); P(cmd, "@Search", 200, $"%{f.Search.Trim()}%"); } cmd.CommandText = $"SELECT TOP(500) [ItemCode],[Descripcion],[NombreExtrangero],[GrupoArticulo],[Ubicacion],[CodCabys],[CodBarras],[Precio],[Moneda],[CodAlterno],[Tarifa],[CodProveedor],[Empaque],[UnidMedida],[TipoProducto],[Familia],[Categoria],[Marca],[SujetoAImpuesto],[CreadoEnSap] FROM [dbo].[Articulos]{(w.Count == 0 ? "" : " WHERE " + string.Join(" AND ", w))} ORDER BY [Id] DESC"; var a = new List<Product>(); await using var r = await cmd.ExecuteReaderAsync(t); while (await r.ReadAsync(t)) a.Add(new(S(r, "ItemCode"), S(r, "Descripcion"), S(r, "NombreExtrangero"), S(r, "GrupoArticulo"), S(r, "Ubicacion"), S(r, "CodCabys"), S(r, "CodBarras"), D(r, "Precio"), S(r, "Moneda"), S(r, "CodAlterno"), D(r, "Tarifa"), S(r, "CodProveedor"), S(r, "Empaque"), S(r, "UnidMedida"), S(r, "TipoProducto"), S(r, "Familia"), S(r, "Categoria"), S(r, "Marca"), B(r, "SujetoAImpuesto"), B(r, "CreadoEnSap"))); return a; }
    public async ValueTask<IReadOnlyCollection<AutomaticDiscount>> ListDiscountsAsync(CancellationToken t) { await using var c = await Open(t); await using var cmd = Command("SELECT [CodArticulo],[Descripcion],[Descuento],[Desde],[hasta],[Cantidad],[Disponible],[Comentario] FROM [dbo].[DescuentosAutomaticos] ORDER BY [CodArticulo]", c); var a = new List<AutomaticDiscount>(); await using var r = await cmd.ExecuteReaderAsync(t); while (await r.ReadAsync(t)) a.Add(new() { ProductCode = S(r, "CodArticulo"), Description = S(r, "Descripcion"), Percentage = D(r, "Descuento"), From = Date(r, "Desde"), To = Date(r, "hasta"), MinimumQuantity = D(r, "Cantidad"), AvailableQuantity = D(r, "Disponible"), Comments = S(r, "Comentario") }); return a; }
    public async ValueTask<bool> SaveDiscountAsync(AutomaticDiscount x, bool n, CancellationToken t) { await using var c = await Open(t); var sql = n ? "INSERT INTO [dbo].[DescuentosAutomaticos]([CodArticulo],[Descripcion],[Descuento],[Desde],[hasta],[Cantidad],[Disponible],[Comentario],[HabilitaDisponible]) VALUES(@Code,@Description,@Discount,@From,@To,@Quantity,@Available,@Comments,@Limited)" : "UPDATE [dbo].[DescuentosAutomaticos] SET [Descripcion]=@Description,[Descuento]=@Discount,[Desde]=@From,[hasta]=@To,[Cantidad]=@Quantity,[Disponible]=@Available,[Comentario]=@Comments,[HabilitaDisponible]=@Limited WHERE [CodArticulo]=@Code"; await using var cmd = Command(sql, c); DiscountParameters(cmd, x); try { return await cmd.ExecuteNonQueryAsync(t) == 1; } catch (SqlException e) when (e.Number is 2601 or 2627) { return false; } }
    public async ValueTask<bool> DeleteDiscountAsync(string code, CancellationToken t) { await using var c = await Open(t); await using var cmd = Command("DELETE FROM [dbo].[DescuentosAutomaticos] WHERE [CodArticulo]=@Code", c); P(cmd, "@Code", 100, code); return await cmd.ExecuteNonQueryAsync(t) > 0; }
    public async ValueTask<IReadOnlyCollection<PriceList>> ListPriceListsAsync(CancellationToken t) { await using var c = await Open(t); await using var cmd = Command("SELECT [idListasDePrecio],[Nombre],[Estado] FROM [dbo].[ListasDePrecio] ORDER BY [Nombre]", c); var a = new List<PriceList>(); await using var r = await cmd.ExecuteReaderAsync(t); while (await r.ReadAsync(t)) a.Add(new(Convert.ToInt32(r[0]), Convert.ToString(r[1])?.Trim() ?? "", Bool(r[2]))); return a; }
    public async ValueTask<int> SavePriceListAsync(PriceList x, bool n, CancellationToken t) { await using var c = await Open(t); var sql = n ? "INSERT INTO [dbo].[ListasDePrecio]([Nombre],[Estado]) OUTPUT INSERTED.[idListasDePrecio] VALUES(@Name,0)" : "UPDATE [dbo].[ListasDePrecio] SET [Nombre]=@Name WHERE [idListasDePrecio]=@Id; SELECT CASE WHEN @@ROWCOUNT=1 THEN @Id ELSE 0 END"; await using var cmd = Command(sql, c); P(cmd, "@Name", 200, x.Name); cmd.Parameters.Add("@Id", SqlDbType.Int).Value = x.Id; try { return Convert.ToInt32(await cmd.ExecuteScalarAsync(t)); } catch (SqlException e) when (e.Number is 2601 or 2627) { return 0; } }
    public async ValueTask<bool> SetPriceListInactiveAsync(int id, bool inactive, CancellationToken t) { await using var c = await Open(t); await using var cmd = Command("UPDATE [dbo].[ListasDePrecio] SET [Estado]=@State WHERE [idListasDePrecio]=@Id", c); cmd.Parameters.Add("@State", SqlDbType.Bit).Value = inactive; cmd.Parameters.Add("@Id", SqlDbType.Int).Value = id; return await cmd.ExecuteNonQueryAsync(t) == 1; }
    private static void DiscountParameters(SqlCommand c, AutomaticDiscount x) { P(c, "@Code", 100, x.ProductCode); P(c, "@Description", 300, x.Description); Decimal(c, "@Discount", x.Percentage); c.Parameters.Add("@From", SqlDbType.Date).Value = x.From.ToDateTime(TimeOnly.MinValue); c.Parameters.Add("@To", SqlDbType.Date).Value = x.To.ToDateTime(TimeOnly.MinValue); Decimal(c, "@Quantity", x.MinimumQuantity); Decimal(c, "@Available", x.AvailableQuantity); P(c, "@Comments", 1000, x.Comments); c.Parameters.Add("@Limited", SqlDbType.Bit).Value = x.AvailableQuantity > 0; }
    private static void Decimal(SqlCommand c, string n, decimal v) { var p = c.Parameters.Add(n, SqlDbType.Decimal); p.Precision = 19; p.Scale = 4; p.Value = v; }
    private static void P(SqlCommand c, string n, int l, string? v) => c.Parameters.Add(n, SqlDbType.NVarChar, l).Value = v?.Trim() ?? ""; private static string S(SqlDataReader r, string n) => Convert.ToString(r[n])?.Trim() ?? ""; private static decimal D(SqlDataReader r, string n) => r[n] is DBNull ? 0 : Convert.ToDecimal(r[n]); private static DateOnly Date(SqlDataReader r, string n) => DateOnly.FromDateTime(Convert.ToDateTime(r[n])); private static bool B(SqlDataReader r, string n) => r[n] is not DBNull && Bool(r[n]); private static bool Bool(object v) => v is bool b ? b : Convert.ToString(v)?.Trim() is "1" or "True" or "TRUE" or "Y" or "SI"; private async ValueTask<SqlConnection> Open(CancellationToken t) { var c = new SqlConnection(connectionString); await c.OpenAsync(t); return c; }
    private SqlCommand Command(string s, SqlConnection c) => new(s, c) { CommandTimeout = timeout };
}
